package com.gymmind.knowledge.infrastructure.parser; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*;
public final class DeterministicChunker { private final int size,overlap; public DeterministicChunker(int size,int overlap){if(size<=0||overlap<0||overlap>=size)throw new IllegalArgumentException("invalid chunk bounds");this.size=size;this.overlap=overlap;} public List<Chunk> chunk(String text,String documentId){if(text==null||text.isBlank()||documentId==null||documentId.isBlank())throw new IllegalArgumentException("empty document");List<Chunk> out=new ArrayList<>();int step=size-overlap,ord=0;for(int start=0;start<text.length();start+=step){int end=Math.min(text.length(),start+size);String part=text.substring(start,end);out.add(new Chunk(hash(documentId+":"+ord+":"+part),documentId,ord++,part));if(end==text.length())break;}return out;} private static String hash(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v));return x.toString();}catch(Exception e){throw new IllegalStateException(e);}} }
